def _ownership_n1_configuration_errors(formal_dir: Path) -> list[str]:
    """Keep the one-validator ownership search on its exact closed model."""

    path = formal_dir / "ownership_n1.cfg"
    if not path.is_file() or path.is_symlink():
        return [
            f"{path}: one-validator ownership configuration must be a regular file"
        ]
    source = path.read_text(encoding="utf-8")
    errors: list[str] = []
    observed_config_sha256 = _sha256_file(path)
    if observed_config_sha256 != _OWNERSHIP_N1_CONFIG_SHA256:
        errors.append(
            f"{path}: one-validator ownership configuration SHA-256 must be "
            f"{_OWNERSHIP_N1_CONFIG_SHA256}; found {observed_config_sha256}"
        )
    model_path = formal_dir / "SumeragiV2OwnershipInvariantCheck.tla"
    if not model_path.is_file() or model_path.is_symlink():
        errors.append(
            f"{model_path}: one-validator ownership model must be a regular file"
        )
    else:
        model_source = model_path.read_text(encoding="utf-8")
        observed_model_sha256 = _sha256_file(model_path)
        if observed_model_sha256 != _OWNERSHIP_N1_MODEL_SHA256:
            errors.append(
                f"{model_path}: one-validator ownership model SHA-256 must be "
                f"{_OWNERSHIP_N1_MODEL_SHA256}; found {observed_model_sha256}"
            )
        exact_operators = {
            "SingleValidatorRosters": "<<<<0>>>>",
            "SingleValidatorPowers": "<<<<1>>>>",
            "OwnershipAllVars": "<<AsyncAllVars, acquisitionVars>>",
            "OwnershipBoundedInit": "/\\ AsyncFiniteInit /\\ AcquisitionInit",
            "OwnershipBoundedNext": (
                "/\\ OwnershipAsyncNext /\\ UNCHANGED acquisitionVars"
            ),
            "OwnershipDebugStutter": "UNCHANGED OwnershipAllVars",
            "OwnershipBoundedSpec": (
                "OwnershipBoundedInit /\\ "
                "[][OwnershipBoundedNext]_OwnershipAllVars"
            ),
            "OwnershipInitialClock": "asyncNow = 0",
        }
        for symbol, expected in exact_operators.items():
            extracted = _top_level_operator_body(
                model_source, symbol, preserve_string_contents=True
            )
            if extracted is None:
                errors.append(
                    f"{model_path}: missing ownership model operator {symbol}"
                )
                continue
            body, line = extracted
            normalized = " ".join(body.split())
            if normalized != expected:
                errors.append(
                    f"{model_path}:{line}: ownership model operator {symbol} "
                    f"must equal only {expected!r}; found {normalized!r}"
                )
        for (
            symbol,
            expected_sha256,
        ) in _OWNERSHIP_N1_STRUCTURAL_OPERATOR_SHA256.items():
            extracted = _top_level_operator_body(
                model_source, symbol, preserve_string_contents=True
            )
            if extracted is None:
                errors.append(
                    f"{model_path}: missing ownership structural helper {symbol}"
                )
                continue
            body, line = extracted
            normalized = " ".join(body.split())
            observed_sha256 = hashlib.sha256(
                normalized.encode("utf-8")
            ).hexdigest()
            if observed_sha256 != expected_sha256:
                errors.append(
                    f"{model_path}:{line}: ownership structural helper {symbol} "
                    "must match exact reviewed body digest "
                    f"{expected_sha256}; found {observed_sha256}"
                )

    observed_overrides = tuple(
        re.findall(
            r"(?m)^  ([A-Za-z_][A-Za-z0-9_]*) <- "
            r"([A-Za-z_][A-Za-z0-9_]*)$",
            source,
        )
    )
    expected_overrides = (
        ("EpochRosters", "SingleValidatorRosters"),
        ("EpochPowers", "SingleValidatorPowers"),
        ("ViewDomain", "FiniteViews"),
        ("LeaderStarts", "StartsHeightZero"),
        ("LaneHashes", "LaneHashesOneHeight"),
        ("DaHashes", "DaHashesOneHeight"),
        *_OWNERSHIP_N1_DEFINITION_OVERRIDES,
    )
    if observed_overrides != expected_overrides:
        errors.append(
            f"{path}: ownership search substitutions must equal the reviewed "
            "six closed-domain assignments followed by the ordered "
            "fifteen-entry structural definition inventory; "
            f"found {observed_overrides}"
        )

    def natural(name: str) -> int | None:
        matches = re.findall(rf"(?m)^  {re.escape(name)} = ([0-9]+)$", source)
        if len(matches) != 1:
            errors.append(
                f"{path}: ownership search must pin {name} exactly once"
            )
            return None
        return int(matches[0])

    validator_count = natural("N")
    ingress_capacity = natural("AsyncIngressCapacity")
    deferred_progress_capacity = natural("AsyncDeferredProgressCapacity")
    if validator_count is not None and validator_count != 1:
        errors.append(f"{path}: ownership search must remain the N=1 boundary")
    if validator_count is not None and ingress_capacity is not None:
        exact_ingress_capacity = 4 * validator_count + 2
        if ingress_capacity != exact_ingress_capacity or ingress_capacity != 6:
            errors.append(
                f"{path}: N=1 AsyncIngressCapacity must equal exact 4 * N + 2 "
                f"geometry (6), found {ingress_capacity}"
            )
    if validator_count is not None and deferred_progress_capacity is not None:
        exact_deferred_capacity = 2 * validator_count + 3
        if (
            deferred_progress_capacity != exact_deferred_capacity
            or deferred_progress_capacity != 5
        ):
            errors.append(
                f"{path}: N=1 AsyncDeferredProgressCapacity must equal exact "
                f"2 * N + 3 geometry (5), found {deferred_progress_capacity}"
            )
    for refinement_constant in (
        "ProductionEnterViewUsesPostInstallEffectiveLock",
        "ProductionBodyOwnershipPreservesEffectiveLock",
        "ProductionBodyCapacityRetirementPreservesEffectiveLock",
        "ProductionBodyServiceRefinesAsyncFairness",
        "ProductionDurableIntentTraceRefinesProgressWitness",
        "ProductionDecisionTraceRefinesRecoveryWitness",
        "ProductionSchedulerTraceRefinesProtectedOwnership",
        "ProductionIngressIdentityAndClassTraceRefinesProtectedOwnership",
        "ProductionTwoStageRelayRetryTraceRefinesSourceFairness",
        "ProductionReliableFlushTraceRefinesOutboundOwnership",
        "ProductionApplicationTraceRefinesDecisionCompletion",
    ):
        if source.count(f"  {refinement_constant} = TRUE\n") != 1:
            errors.append(
                f"{path}: ownership search must assign "
                f"{refinement_constant} = TRUE exactly once"
            )
    for exact_line in (
        "SPECIFICATION OwnershipBoundedSpec",
        "CHECK_DEADLOCK FALSE",
        "CONSTRAINT OwnershipInitialClock",
        "INVARIANT AsyncTypeInvariant",
        "INVARIANT AsyncProgressOwnershipInvariant",
        "  EpochRosters <- SingleValidatorRosters",
        "  EpochPowers <- SingleValidatorPowers",
        '  ValidSubjects = {"A"}',
        "  AcquisitionSubjects = {AcquisitionSubjectA}",
        "  InitialAcquisitionSubject = AcquisitionSubjectA",
        "  MaxAcquisitionLockRound = 1",
        "  MaxAcquisitionConsumerView = 1",
        "  MaxAcquisitionGeneration = 1",
        "  MaxAcquisitionId = 4",
    ):
        if source.splitlines().count(exact_line) != 1:
            errors.append(
                f"{path}: ownership search must retain exact closed assignment "
                f"{exact_line!r} once"
            )
    return errors


def _canonical_sidecar_request_identity_source_errors(
    merge_path: Path,
    merge_source: str,
) -> list[str]:
    """Seal every durable coordinate of one semantic request occurrence."""

    errors: list[str] = []
    canonical_request_id_item = _require_qualified_rust_item(
        merge_path,
        merge_source,
        "CertifiedMergeSidecarRequestV1",
        "canonical_request_id",
        errors,
        "canonical semantic sidecar request identity production item",
        expected_attributes=("#[must_use]",),
    )
    _require_exact_rust_tokens(
        merge_path,
        canonical_request_id_item,
        """
pub fn canonical_request_id(&self) -> Hash {
    let version = [self.version];
    let service_generation = self.service_generation.get().to_le_bytes();
    let stream_epoch = self.stream_epoch.get().to_le_bytes();
    let semantic_sequence = self.semantic_sequence.get().to_le_bytes();
    let encoded_len = self.encoded_len.to_le_bytes();
    let epoch_id = self.epoch_id.to_le_bytes();
    let requester = self.requester.encode();
    let responder = self.responder.encode();
    Hash::new_from_chunks(&[
        REQUEST_ID_DOMAIN,
        &version,
        &service_generation,
        &stream_epoch,
        &semantic_sequence,
        self.entry_hash.as_ref().as_ref(),
        &encoded_len,
        &epoch_id,
        self.reference_digest.as_ref(),
        requester.as_slice(),
        responder.as_slice(),
    ])
}
""",
        "canonical semantic request identity must bind every immutable request coordinate while excluding only the cumulative close floor",
        errors,
    )
    for occurrence_coordinate in (
        "self.service_generation",
        "self.stream_epoch",
        "self.semantic_sequence",
    ):
        _require_rust_token_sequence(
            merge_path,
            canonical_request_id_item,
            occurrence_coordinate,
            "canonical semantic request identity must bind every durable occurrence coordinate exactly once",
            errors,
            count=1,
        )
    _require_rust_token_sequence(
        merge_path,
        canonical_request_id_item,
        "self.closed_through",
        "canonical semantic request identity must exclude the monotonically advancing cumulative close floor",
        errors,
        count=0,
    )
    return errors


def _canonical_sidecar_request_identity_errors(
    repo_root: Path = ROOT_DIR,
) -> list[str]:
    """Load and validate the canonical sidecar request identity production item."""

    merge_path = repo_root / "crates" / "iroha_core" / "src" / "merge_sidecar.rs"
    if not merge_path.is_file() or merge_path.is_symlink():
        return [
            f"{merge_path}: canonical semantic sidecar request identity source "
            "must be a regular file"
        ]
    return _canonical_sidecar_request_identity_source_errors(
        merge_path,
        merge_path.read_text(encoding="utf-8"),
    )


